// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    SimpleWallet c;
    function setUp() public { c = new SimpleWallet(); }

    receive() external payable {}

    function testFuzz_property(uint256 amount, uint256 value) public {
        // admissible domain: positive funding, partial withdrawal strictly below balance
        uint256 a = bound(amount, 1 ether, 1000 ether);
        vm.assume(value > 0 && value < a);

        // fund the contract via its payable fallback
        vm.deal(address(this), a);
        (bool funded, ) = address(c).call{value: a}("");
        require(funded, "funding failed");

        // owner (the deployer, i.e. this test contract) withdraws exactly `value`
        vm.prank(address(this));
        bool ok;
        try c.withdraw(value) {
            ok = true;
        } catch {
            ok = false;
        }

        // rule: a successful owner withdraw(v) removes exactly v wei,
        // leaving (funded - v) in the contract
        assertTrue(ok && address(c).balance == a - value);
    }
}
